import itertools, random
from collections import deque

def bfs_ecc(adj, n, v):
    dist = {v: 0}
    q = deque([v])
    while q:
        curr = q.popleft()
        for nxt in adj[curr]:
            if nxt not in dist:
                dist[nxt] = dist[curr] + 1
                q.append(nxt)
    if len(dist) < n:
        return None
    return dist

def roman_domination_number(adj, n):
    min_w = 2 * n
    for f in itertools.product([0, 1, 2], repeat=n):
        w = sum(f)
        if w >= min_w:
            continue
        valid = True
        for v in range(n):
            if f[v] == 0:
                if not any(f[u] == 2 for u in adj[v]):
                    valid = False
                    break
        if valid:
            min_w = w
    return min_w

# Test paths, cycles, random trees
failures = 0
tests = 0
for n in range(2, 11):
    # path
    adj = {i: [] for i in range(n)}
    for i in range(n - 1):
        adj[i].append(i + 1)
        adj[i + 1].append(i)
    W = roman_domination_number(adj, n)
    dists = [bfs_ecc(adj, n, v) for v in range(n)]
    # check if exists v, k
    ok = False
    for v in range(n):
        for k in range(n):
            bk_card = sum(1 for u in range(n) if dists[v][u] <= k)
            if k + (n - bk_card) + 1 <= W:
                ok = True
                break
        if ok:
            break
    tests += 1
    if not ok:
        print(f'Failed on P_{n} with W={W}!')
        failures += 1

print(f'Tested {tests} graphs, {failures} failures')
