import random, itertools
from collections import deque

def bfs_ecc(adj, n, v):
    dist = {v: 0}
    q = deque([v])
    while q:
        curr = q.popleft()
        for nxt in adj[curr]:
            if nxt not in dist:
                dist[nxt] = dist[curr] + 1
                q.append(nxt)
    if len(dist) < n:
        return None
    return max(dist.values())

def roman_domination_number(adj, n):
    # MIP or quick search
    min_w = 2 * n
    for f in itertools.product([0, 1, 2], repeat=n):
        w = sum(f)
        if w >= min_w: continue
        valid = True
        for v in range(n):
            if f[v] == 0 and not any(f[u] == 2 for u in adj[v]):
                valid = False; break
        if valid: min_w = w
    return min_w

# Test 200 random connected Erdos-Renyi graphs on n = 7, 8
found_ce = False
for n in [7, 8]:
    for p in [0.15, 0.2, 0.25, 0.3, 0.4]:
        for trial in range(30):
            adj = {i: [] for i in range(n)}
            for i in range(n):
                for j in range(i + 1, n):
                    if random.random() < p:
                        adj[i].append(j); adj[j].append(i)
            # check connected
            eccs = [bfs_ecc(adj, n, i) for i in range(n)]
            if any(e is None for e in eccs): continue
            rad = min(eccs)
            rdn = roman_domination_number(adj, n)
            if rad + 1 > rdn:
                print(f'COUNTEREXAMPLE FOUND! n={n}, p={p}, rad={rad}, rdn={rdn}')
                found_ce = True
                break
        if found_ce: break
    if found_ce: break

if not found_ce:
    print('No counterexamples among random general graphs on n=7, 8!')
